#include <iostream>
#include <string>

// Conceptual representation of the Header file content
class GradeBookMock {
public:
    explicit GradeBookMock(std::string name);
    void setCourseName(std::string name);
    std::string getCourseName() const;
    void displayMessage() const;
private:
    std::string courseName; // Data member dictates object size
};

// Conceptual representation of the Implementation (.cpp) file content
GradeBookMock::GradeBookMock(std::string name) : courseName(std::move(name)) {}
void GradeBookMock::setCourseName(std::string name) { courseName = std::move(name); }
std::string GradeBookMock::getCourseName() const { return courseName; }
void GradeBookMock::displayMessage() const {
    std::cout << "Welcome to the grade book for\n" << getCourseName() << "!\n";
}

// Client code
int main() {
    GradeBookMock gb1("CS101 Introduction to C++ Programming");
    std::cout << "Object size in bytes: " << sizeof(gb1) << "\n";
    std::cout << "courseName size: " << sizeof(std::string) << "\n";
    gb1.displayMessage();
    return 0;
}

#include <iostream>
#include <string>
#include <utility>

// ==================== GradeBook.h ====================
class GradeBook {
public:
    explicit GradeBook(std::string courseName);
    void setCourseName(std::string courseName);
    std::string getCourseName() const;
    void displayMessage() const;
private:
    std::string courseName;
};

// ==================== GradeBook.cpp ==================
GradeBook::GradeBook(std::string name) 
    : courseName(std::move(name)) {} // Member initializer

void GradeBook::setCourseName(std::string name) {
    courseName = std::move(name);
}

std::string GradeBook::getCourseName() const {
    return courseName;
}

void GradeBook::displayMessage() const {
    std::cout << "Welcome to the grade book for\n"
              << getCourseName() << "!\n";
}

// ==================== main.cpp =======================
int main() {
    GradeBook gradeBook1("CS101 Introduction to C++ Programming");
    GradeBook gradeBook2("CS102 Data Structures in C++");

    std::cout << "gradeBook1 created for course: " << gradeBook1.getCourseName()
              << "\ngradeBook2 created for course: " << gradeBook2.getCourseName()
              << "\n";

    return 0;
}
